CREATE OR REPLACE VIEW public.admin_zoek_bronnen AS
SELECT 'ondernemingen'::text bron, 'klanten'::text groep,t.id,concat_ws(' ',nullif(t.naam,''),nullif(t.afas_contactpersoon,''),nullif(t.kvk_naam,''),nullif(t.exact_account_naam,'')) titel,lower(coalesce(t.naam,'') || ' ' || coalesce(t.afas_contactpersoon,'') || ' ' || coalesce(t.kvk_naam,'') || ' ' || coalesce(t.exact_account_naam,'') || ' ' || coalesce(t.factuur_email,'') || ' ' || coalesce(t.kvk,'') || ' ' || coalesce(t.exact_relatie_code,'') || ' ' || coalesce(t.postcode,'') || ' ' || coalesce(t.kvk_postcode,'')) || ' ' || lower(coalesce(array_to_string(t.kvk_handelsnamen,' '),'')) zoektekst,ARRAY[]::text[] telefoons,ARRAY[t.kvk,t.exact_relatie_code,t.postcode,t.kvk_postcode]::text[] nummers,ARRAY[t.iban]::text[] ibans,NULL::uuid lead_id,id onderneming_id,NULL::uuid persoon_id,'/admin/klanten/'::text route,coalesce(to_jsonb(t)->>'status','') status,coalesce(to_jsonb(t)->>'type','') soort,coalesce((to_jsonb(t)->>'is_test')::boolean,false) is_test,coalesce(NULLIF(t.factuur_email,''),NULL::text) email FROM public.ondernemingen t
UNION ALL
SELECT 'leads'::text bron, 'leads'::text groep,t.id,concat_ws(' ',nullif(t.voornaam,''),nullif(t.achternaam,''),nullif(t.bedrijfsnaam,'')) titel,lower(coalesce(t.voornaam,'') || ' ' || coalesce(t.achternaam,'') || ' ' || coalesce(t.bedrijfsnaam,'') || ' ' || coalesce(t.email,'') || ' ' || coalesce(t.kvk_nummer,'') || ' ' || coalesce(t.exact_relatie_code,'') || ' ' || coalesce(t.adres_postcode,'')) || ' ' || lower(coalesce(t.extra_data->'formulier','[]'::jsonb)::text) zoektekst,ARRAY[t.telefoon]::text[] telefoons,ARRAY[t.kvk_nummer,t.exact_relatie_code,t.adres_postcode]::text[] nummers,ARRAY[t.iban]::text[] ibans,id lead_id,NULL::uuid onderneming_id,NULL::uuid persoon_id,'/admin/leads/'::text route,coalesce(to_jsonb(t)->>'status','') status,coalesce(to_jsonb(t)->>'type','') soort,coalesce((to_jsonb(t)->>'is_test')::boolean,false) is_test,coalesce(NULLIF(t.email,''),NULL::text) email FROM public.leads t
UNION ALL
SELECT 'aanvraag_concepten'::text bron, 'afgehaakt'::text groep,t.id,concat_ws(' ',nullif(t.voornaam,''),nullif(t.achternaam,''),nullif(t.bedrijfsnaam,'')) titel,lower(coalesce(t.voornaam,'') || ' ' || coalesce(t.achternaam,'') || ' ' || coalesce(t.bedrijfsnaam,'') || ' ' || coalesce(t.email,'') || ' ' || coalesce(t.kvk,'')) zoektekst,ARRAY[t.telefoon]::text[] telefoons,ARRAY[t.kvk]::text[] nummers,ARRAY[]::text[] ibans,lead_id lead_id,NULL::uuid onderneming_id,NULL::uuid persoon_id,'/admin/afgehaakt?record='::text route,coalesce(to_jsonb(t)->>'status','') status,coalesce(to_jsonb(t)->>'type','') soort,coalesce((to_jsonb(t)->>'is_test')::boolean,false) is_test,coalesce(NULLIF(t.email,''),NULL::text) email FROM public.aanvraag_concepten t
UNION ALL
SELECT 'bav_aanmeldingen'::text bron, 'aanmeldingen'::text groep,t.id,concat_ws(' ',nullif(t.voornaam,''),nullif(t.achternaam,''),nullif(t.bedrijfsnaam,'')) titel,lower(coalesce(t.voornaam,'') || ' ' || coalesce(t.achternaam,'') || ' ' || coalesce(t.bedrijfsnaam,'') || ' ' || coalesce(t.email,'') || ' ' || coalesce(t.kvk_nummer,'') || ' ' || coalesce(t.exact_abonnement_id,'')) zoektekst,ARRAY[t.telefoon]::text[] telefoons,ARRAY[t.kvk_nummer,t.exact_abonnement_id]::text[] nummers,ARRAY[t.iban]::text[] ibans,lead_id lead_id,NULL::uuid onderneming_id,NULL::uuid persoon_id,'/admin/aanvragen?bav='::text route,coalesce(to_jsonb(t)->>'status','') status,coalesce(to_jsonb(t)->>'type','') soort,coalesce((to_jsonb(t)->>'is_test')::boolean,false) is_test,coalesce(NULLIF(t.email,''),NULL::text) email FROM public.bav_aanmeldingen t
UNION ALL
SELECT 'personen'::text bron, 'personen'::text groep,t.id,concat_ws(' ',nullif(t.voornaam,''),nullif(t.achternaam,'')) titel,lower(coalesce(t.voornaam,'') || ' ' || coalesce(t.achternaam,'') || ' ' || coalesce(t.genormaliseerd_email,'') || ' ' || coalesce(t.email_weergave,'')) zoektekst,ARRAY[t.telefoon]::text[] telefoons,ARRAY[]::text[] nummers,ARRAY[]::text[] ibans,NULL::uuid lead_id,(SELECT po.onderneming_id FROM public.persoon_onderneming po WHERE po.persoon_id=t.id ORDER BY po.created_at LIMIT 1) onderneming_id,NULL::uuid persoon_id,'/admin/personen/'::text route,coalesce(to_jsonb(t)->>'status','') status,coalesce(to_jsonb(t)->>'type','') soort,coalesce((to_jsonb(t)->>'is_test')::boolean,false) is_test,coalesce(NULLIF(t.genormaliseerd_email,''),NULLIF(t.email_weergave,''),NULL::text) email FROM public.personen t
UNION ALL
SELECT 'klant_contracten'::text bron, 'contracten'::text groep,t.id,concat_ws(' ',nullif(t.product,'')) titel,lower(coalesce(t.product,'') || ' ' || coalesce(t.abonnement_nr,'')) zoektekst,ARRAY[]::text[] telefoons,ARRAY[t.abonnement_nr]::text[] nummers,ARRAY[]::text[] ibans,cyber_lead_id lead_id,onderneming_id onderneming_id,NULL::uuid persoon_id,'/admin/klanten/'::text route,coalesce(to_jsonb(t)->>'status','') status,coalesce(to_jsonb(t)->>'type','') soort,coalesce((to_jsonb(t)->>'is_test')::boolean,false) is_test,coalesce(NULL::text) email FROM public.klant_contracten t
UNION ALL
SELECT 'policies'::text bron, 'polissen'::text groep,t.id,concat_ws(' ',nullif(t.certificate_holder,''),nullif(t.insured_name,'')) titel,lower(coalesce(t.certificate_holder,'') || ' ' || coalesce(t.insured_name,'') || ' ' || coalesce(t.certificate_number,'')) zoektekst,ARRAY[]::text[] telefoons,ARRAY[t.certificate_number]::text[] nummers,ARRAY[]::text[] ibans,lead_id lead_id,NULL::uuid onderneming_id,NULL::uuid persoon_id,'/admin/leads/'::text route,coalesce(to_jsonb(t)->>'status','') status,coalesce(to_jsonb(t)->>'type','') soort,coalesce((to_jsonb(t)->>'is_test')::boolean,false) is_test,coalesce(NULL::text) email FROM public.policies t
UNION ALL
SELECT 'klant_certificaten'::text bron, 'certificaten'::text groep,t.id,concat_ws(' ',nullif(t.bron_naam,''),nullif(t.bron_contact,'')) titel,lower(coalesce(t.bron_naam,'') || ' ' || coalesce(t.bron_contact,'') || ' ' || coalesce(t.certificaatnummer,'')) zoektekst,ARRAY[]::text[] telefoons,ARRAY[t.certificaatnummer]::text[] nummers,ARRAY[]::text[] ibans,NULL::uuid lead_id,onderneming_id onderneming_id,persoon_id persoon_id,'/admin/klanten/'::text route,coalesce(to_jsonb(t)->>'status','') status,coalesce(to_jsonb(t)->>'type','') soort,coalesce((to_jsonb(t)->>'is_test')::boolean,false) is_test,coalesce(NULL::text) email FROM public.klant_certificaten t
UNION ALL
SELECT 'cyber_toevoeg_verzoeken'::text bron, 'cyber'::text groep,t.id,concat_ws(' ',nullif(t.notitie,'')) titel,lower(coalesce(t.notitie,'')) zoektekst,ARRAY[]::text[] telefoons,ARRAY[]::text[] nummers,ARRAY[]::text[] ibans,lead_id lead_id,onderneming_id onderneming_id,NULL::uuid persoon_id,'/admin/aanvragen?cyber='::text route,coalesce(to_jsonb(t)->>'status','') status,coalesce(to_jsonb(t)->>'type','') soort,coalesce((to_jsonb(t)->>'is_test')::boolean,false) is_test,coalesce(NULL::text) email FROM public.cyber_toevoeg_verzoeken t
UNION ALL
SELECT 'klant_service_aanvragen'::text bron, 'service'::text groep,t.id,concat_ws(' ',nullif(t.voornaam,''),nullif(t.achternaam,'')) titel,lower(coalesce(t.voornaam,'') || ' ' || coalesce(t.achternaam,'') || ' ' || coalesce(t.email,'') || ' ' || coalesce(t.polisnummer,'')) || ' ' || lower(coalesce(t.details->>'bedrijfsnaam','')) || ' ' || lower(coalesce(t.details->>'postcode','')) zoektekst,ARRAY[t.telefoon]::text[] telefoons,ARRAY[t.polisnummer]::text[] nummers,ARRAY[]::text[] ibans,NULL::uuid lead_id,onderneming_id onderneming_id,NULL::uuid persoon_id,'/admin/service-aanvragen/'::text route,coalesce(to_jsonb(t)->>'status','') status,coalesce(to_jsonb(t)->>'type','') soort,coalesce((to_jsonb(t)->>'is_test')::boolean,false) is_test,coalesce(NULLIF(t.email,''),NULL::text) email FROM public.klant_service_aanvragen t
UNION ALL
SELECT 'aov_aanmeldingen'::text bron, 'aov'::text groep,t.id,concat_ws(' ',nullif(t.naam,'')) titel,lower(coalesce(t.naam,'') || ' ' || coalesce(t.email,'')) zoektekst,ARRAY[t.telefoon]::text[] telefoons,ARRAY[]::text[] nummers,ARRAY[]::text[] ibans,NULL::uuid lead_id,NULL::uuid onderneming_id,NULL::uuid persoon_id,'/admin/aov-doorverwijzingen?record='::text route,coalesce(to_jsonb(t)->>'status','') status,coalesce(to_jsonb(t)->>'type','') soort,coalesce((to_jsonb(t)->>'is_test')::boolean,false) is_test,coalesce(NULLIF(t.email,''),NULL::text) email FROM public.aov_aanmeldingen t
UNION ALL
SELECT 'screening_aanvragen'::text bron, 'screening'::text groep,t.id,concat_ws(' ',nullif(t.voornaam,''),nullif(t.achternaam,''),nullif(t.bedrijfsnaam,'')) titel,lower(coalesce(t.voornaam,'') || ' ' || coalesce(t.achternaam,'') || ' ' || coalesce(t.bedrijfsnaam,'') || ' ' || coalesce(t.email,'') || ' ' || coalesce(t.kvk_nummer,'')) zoektekst,ARRAY[t.telefoon]::text[] telefoons,ARRAY[t.kvk_nummer]::text[] nummers,ARRAY[t.iban]::text[] ibans,NULL::uuid lead_id,NULL::uuid onderneming_id,NULL::uuid persoon_id,'/admin/screening-aanvragen/'::text route,coalesce(to_jsonb(t)->>'status','') status,coalesce(to_jsonb(t)->>'type','') soort,coalesce((to_jsonb(t)->>'is_test')::boolean,false) is_test,coalesce(NULLIF(t.email,''),NULL::text) email FROM public.screening_aanvragen t
UNION ALL
SELECT 'collective_signups'::text bron, 'collectief'::text groep,t.id,concat_ws(' ',nullif(t.naam,'')) titel,lower(coalesce(t.naam,'') || ' ' || coalesce(t.email,'') || ' ' || coalesce(t.postcode,'')) zoektekst,ARRAY[t.telefoon]::text[] telefoons,ARRAY[t.postcode]::text[] nummers,ARRAY[]::text[] ibans,NULL::uuid lead_id,NULL::uuid onderneming_id,NULL::uuid persoon_id,'/admin/zoekrecord/collective_signups/'::text route,coalesce(to_jsonb(t)->>'status','') status,coalesce(to_jsonb(t)->>'type','') soort,coalesce((to_jsonb(t)->>'is_test')::boolean,false) is_test,coalesce(NULLIF(t.email,''),NULL::text) email FROM public.collective_signups t
UNION ALL
SELECT 'collective_suggestions'::text bron, 'collectief'::text groep,t.id,concat_ws(' ',nullif(t.naam,'')) titel,lower(coalesce(t.naam,'') || ' ' || coalesce(t.email,'')) zoektekst,ARRAY[]::text[] telefoons,ARRAY[]::text[] nummers,ARRAY[]::text[] ibans,NULL::uuid lead_id,NULL::uuid onderneming_id,NULL::uuid persoon_id,'/admin/zoekrecord/collective_suggestions/'::text route,coalesce(to_jsonb(t)->>'status','') status,coalesce(to_jsonb(t)->>'type','') soort,coalesce((to_jsonb(t)->>'is_test')::boolean,false) is_test,coalesce(NULLIF(t.email,''),NULL::text) email FROM public.collective_suggestions t
UNION ALL
SELECT 'collective_newsletter'::text bron, 'collectief'::text groep,t.id,''::text titel,lower(coalesce(t.email,'')) zoektekst,ARRAY[]::text[] telefoons,ARRAY[]::text[] nummers,ARRAY[]::text[] ibans,NULL::uuid lead_id,NULL::uuid onderneming_id,NULL::uuid persoon_id,'/admin/zoekrecord/collective_newsletter/'::text route,coalesce(to_jsonb(t)->>'status','') status,coalesce(to_jsonb(t)->>'type','') soort,coalesce((to_jsonb(t)->>'is_test')::boolean,false) is_test,coalesce(NULLIF(t.email,''),NULL::text) email FROM public.collective_newsletter t
UNION ALL
SELECT 'klant_mandaten'::text bron, 'mandaten'::text groep,t.id,''::text titel,lower(coalesce(t.relatiecode,'') || ' ' || coalesce(t.kenmerk,'')) zoektekst,ARRAY[]::text[] telefoons,ARRAY[t.relatiecode,t.kenmerk]::text[] nummers,ARRAY[t.iban]::text[] ibans,NULL::uuid lead_id,onderneming_id onderneming_id,NULL::uuid persoon_id,'/admin/klanten/'::text route,coalesce(to_jsonb(t)->>'status','') status,coalesce(to_jsonb(t)->>'type','') soort,coalesce((to_jsonb(t)->>'is_test')::boolean,false) is_test,coalesce(NULL::text) email FROM public.klant_mandaten t
UNION ALL
